using Rhino;
namespace RhinoContextAssist;
internal sealed class ContextAssistSettings{readonly PersistentSettings s;internal bool Enabled{get;set;}internal int PrimaryCount{get;set;}internal int Margin{get;set;}internal HudCorner Corner{get;set;}internal int TooltipDelay{get;set;}internal Dictionary<string,ActionPreference> Preferences{get;}=new();internal ContextAssistSettings(PersistentSettings p){s=p;Enabled=s.GetBool("Enabled",true);PrimaryCount=s.GetInteger("Primary",5);Margin=s.GetInteger("Margin",70);Corner=s.GetEnumValue("Corner",HudCorner.Auto);TooltipDelay=s.GetInteger("TooltipDelay",180);}internal bool Favorite(string id)=>Preferences.TryGetValue(id,out var p)&&p.Favorite;internal void Toggle(string id){var p=Preferences.TryGetValue(id,out var x)?x:new(id,false,0);Preferences[id]=p with{Favorite=!p.Favorite};}internal IReadOnlyList<ContextAction> Sort(IEnumerable<ContextAction>a)=>a.OrderByDescending(x=>Favorite(x.Id)).ThenByDescending(x=>Preferences.TryGetValue(x.Id,out var p)?p.Used:0).ToList();internal void Used(string id){var p=Preferences.TryGetValue(id,out var x)?x:new(id,false,0);Preferences[id]=p with{Used=p.Used+1};}internal void Save(){s.SetBool("Enabled",Enabled);s.SetInteger("Primary",PrimaryCount);s.SetInteger("Margin",Margin);s.SetEnumValue("Corner",Corner);s.SetInteger("TooltipDelay",TooltipDelay);}}
